"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["30078"],{39435(e){e.exports=JSON.parse('{"id":"F485","slug":"market-manipulation-ratios","name":"Market Manipulation Screens: Order-to-Trade and Cancel Ratios","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Market manipulation","level":"Intermediate","aliases":["spoofing","layering","wash trading","order-to-trade ratio","cancellation rate"],"formula":{"latex":"OTR=\\\\frac{\\\\text{Orders}}{\\\\text{Trades}},\\\\quad \\\\text{Cancel rate}=\\\\frac{\\\\text{Canceled}}{\\\\text{Orders}},\\\\quad \\\\text{Self-match}=\\\\frac{V_{self}}{V_{total}}","also":[],"text":"Order-to-trade ratio = orders entered / trades executed; Cancellation rate = orders canceled / orders entered; Self-trade share = volume where the same beneficial owner is on both sides / total volume; Very high ratios and quick cancellations are warning signs of spoofing or layering, and a high self-trade share of wash trading"},"symbols":[{"symbol":"Orders","meaning":"Orders entered in the period","unit":"count"},{"symbol":"Trades","meaning":"Orders that were executed","unit":"count"},{"symbol":"V_self","meaning":"Volume traded with oneself (no change in true ownership)","unit":"shares"}],"when_to_use":"Use it to see how exchanges and regulators screen for manipulation. Placing large orders and canceling them before execution (spoofing) gives a false view of demand; trading with oneself (wash trades) gives a false view of volume. A high ratio is a flag to investigate, since market makers can also have high ratios for legitimate reasons.","worked_example":{"problem":"In one day an account entered 50,000 orders, had 400 trades and canceled 48,000 orders. 5% of its volume was against itself. The exchange flags accounts with a ratio above 100 and a cancellation rate above 90%.","inputs":{"o":50000,"t":400,"c":48000,"s":5,"lim":100,"cl":90},"steps":[{"label":"Order-to-trade ratio","working":"50000 / 400","value":"125.0"},{"label":"Cancellation rate","working":"48000 / 50000","value":"96.0%"},{"label":"Self-trade share","working":"0.05","value":"5.0%"},{"label":"Orders not canceled","working":"1-0.96","value":"4.0%"},{"label":"Flag (1 = both limits exceeded)","working":"1 if (125>100 and 0.96>0.9) else 0","value":"1"}],"answer":"The order-to-trade ratio is 125.0 and the cancellation rate is 96.0%. Both exceed the limits of 100 and 90%, so the account is flagged (flag = 1). Self-trading is 5.0% of volume. The share of orders that stayed live or filled is 4.0%."},"calculator":{"available":true,"inputs":[{"id":"o","label":"Orders entered","unit":"count","type":"number","default":50000,"hint":""},{"id":"t","label":"Trades executed","unit":"count","type":"number","default":400,"hint":""},{"id":"c","label":"Orders canceled","unit":"count","type":"number","default":48000,"hint":""},{"id":"s","label":"Self-trade share of volume","unit":"%","type":"number","default":5,"hint":""},{"id":"lim","label":"Ratio limit","unit":"","type":"number","default":100,"hint":""},{"id":"cl","label":"Cancellation limit","unit":"%","type":"number","default":90,"hint":""}],"checks":[{"expr":"o>0 and t>0","message":"Orders and trades must be above zero."}],"steps":[{"id":"otr","label":"Order-to-trade ratio","expr":"o/t","format":"num1"},{"id":"cr","label":"Cancellation rate","expr":"c/o","format":"pct1"},{"id":"st","label":"Self-trade share","expr":"s","format":"pct1"},{"id":"live","label":"Orders not canceled","expr":"1-cr","format":"pct1"},{"id":"flag_","label":"Flag (1 = both limits exceeded)","expr":"1 if (otr>lim and cr>cl) else 0","format":"num0"}],"results":["otr","cr","st","flag_"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"otr":125,"cr":0.96,"st":0.05,"live":4.0000000000000036e-2,"flag_":1}},"finder":{"finds":"Whether trading patterns look like manipulation","needs":"Orders, trades, cancellations, self-trade share, limits"},"related":[{"slug":"abnormal-return-event-window","name":"Cumulative Abnormal Return before an Announcement"},{"slug":"bid-ask-spread","name":"Bid-Ask Spread and Trading Cost"},{"slug":"classification-metrics","name":"Classification Metrics: Precision, Recall and F1"}],"related_ids":["F483","F261","F417"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>O</mi><mi>T</mi><mi>R</mi><mo>=</mo><mfrac><mtext>Orders</mtext><mtext>Trades</mtext></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Cancel\xa0rate</mtext><mo>=</mo><mfrac><mtext>Canceled</mtext><mtext>Orders</mtext></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Self-match</mtext><mo>=</mo><mfrac><msub><mi>V</mi><mrow><mi>s</mi><mi>e</mi><mi>l</mi><mi>f</mi></mrow></msub><msub><mi>V</mi><mrow><mi>t</mi><mi>o</mi><mi>t</mi><mi>a</mi><mi>l</mi></mrow></msub></mfrac></mrow><annotation encoding=\\"application/x-tex\\">OTR=\\\\frac{\\\\text{Orders}}{\\\\text{Trades}},\\\\quad \\\\text{Cancel rate}=\\\\frac{\\\\text{Canceled}}{\\\\text{Orders}},\\\\quad \\\\text{Self-match}=\\\\frac{V_{self}}{V_{total}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"margin-call-price","name":"Margin Call Price"},"next":{"slug":"market-ratios-pb-ps-ev","name":"Market Ratios: P/B, P/S and EV/EBITDA"},"lesson":null,"total":522}')}}]);